import { ButtonStyleClass } from '../components/atoms/button/button';
import { TextStyleClass } from '../components/atoms/text/text';
import { LayoutStyleClass } from '../components/molecules/layout/layout';
import { SelectStyleClass } from '../components/molecules/select/select';
import type { ColorToken } from '../core/color';
import { Theme, type ThemeName } from '../core/theme';
import { type Breakpoint, breakpoints } from '../tokens/breakpoints';
import { type Typography, typographyTokens } from '../tokens/typography';
import { getAllStyleClasses } from './extractor';

// ----------------------------------------------------------------------------
// TYPES
// ----------------------------------------------------------------------------
interface DesignSystemConfig {
  classes: string[];
  css: string;
  instance: {
    [Key in ThemeName]?: Theme;
  };
  theme: {
    breakpoints: Breakpoint;
    colors: Partial<ColorToken> & { [Key in ThemeName]?: Partial<ColorToken> };
    fonts: Typography;
  };
}

// ----------------------------------------------------------------------------
// FUNCTIONS
// ----------------------------------------------------------------------------
const initializeTheme = async (name: ThemeName) => {
  return await Theme.generateTheme(name);
};

const initializeThemes = async () => {
  return await Theme.generateThemes();
};

const initializeDesignSystem = async () => {
  const styles = {
    button: ButtonStyleClass,
    layout: LayoutStyleClass,
    select: SelectStyleClass,
    text: TextStyleClass,
  };

  // Example: If layoutStyles is forcing flex or container widths, remove or override them.
  // layoutStyles.container = ''; // or override with display: block styles

  const themes = await initializeThemes();
  const instance = Object.fromEntries(
    themes.map((theme: any) => [theme.name, theme.instance])
  );

  const colorsArray: DesignSystemConfig['theme']['colors'][] = [];

  const defaultTheme = themes.find((theme: any) => theme.name === 'default');
  colorsArray.push({
    ...defaultTheme!.designTokens.colors,
  });

  const cssArray: string[] = [];
  const classesArray = [...getAllStyleClasses(styles)];

  for (const theme of themes) {
    classesArray.push(...theme.designTokens.classes);
    cssArray.push(theme.designTokens.css);
    colorsArray.push({
      [theme.name]: theme.designTokens.colors,
    });
  }

  const colors: DesignSystemConfig['theme']['colors'] = Object.assign(
    {},
    ...new Set(colorsArray)
  );
  const classes = [...new Set(classesArray)];
  const css = [...new Set(cssArray)].join('\n');

  const designSystemConfig: DesignSystemConfig = {
    classes,
    css,
    instance,
    theme: {
      breakpoints,
      colors,
      fonts: typographyTokens,
    },
  };

  return designSystemConfig;
};

export type { DesignSystemConfig };
export { initializeDesignSystem, initializeTheme, initializeThemes };

import type { Typography } from '../tokens/typography';
import type { ColorConfig, ColorPalette } from './color';

import { Color } from './color';

// ----------------------------------------------------------------------------
// TYPES
// ----------------------------------------------------------------------------
type ThemeName = (typeof themes)[number];
interface ThemeProps<T extends keyof ColorPalette = keyof ColorPalette> {
  baseColors: Pick<ColorPalette, T>;
  description: string;
  designTokens: ColorConfig;
  displayName: string;
  instance: Theme;
  name: ThemeName | (string & {});
  typography: Omit<Typography, 'fontSize' | 'fontWeight' | 'lineHeight'>;
}

// ----------------------------------------------------------------------------
// CONSTANTS
// ----------------------------------------------------------------------------
const themes = ['default', 'solarized'] as const;
const defaultThemeBaseColors: ColorPalette = {
  accent: '#28A745', // Energetic green
  error: '#DC3545', // Red
  info: '#17A2B8', // Blue
  neutral: '#6C757D', // Neutral gray
  primary: '#007BFF', // Bright blue
  secondary: '#6C757D', // Neutral gray
  success: '#28A745', // Green
  warning: '#FFC107', // Yellow
} as const;

// ----------------------------------------------------------------------------
// THEME ABSTRACT CLASS
// ----------------------------------------------------------------------------
abstract class Theme {
  protected abstract baseColors: ColorPalette;
  protected abstract description: ThemeProps['description'];
  protected abstract displayName: ThemeProps['displayName'];
  protected abstract name: ThemeProps['name'];
  protected abstract typography: ThemeProps['typography'];

  protected constructor(name: ThemeName) {
    if (!themes.includes(name)) {
      throw new Error(`Theme ${name} not found`);
    }
  }

  static async generateTheme(name: ThemeName): Promise<ThemeProps> {
    if (!themes.includes(name)) {
      throw new Error(`Theme ${name} not found`);
    }

    const themeModule = await import(`../themes/${name}.ts`);
    const themeInstance = new themeModule.default(name);

    const { name: themeName, baseColors } = themeInstance;

    const colorGenerator = new Color(themeName, baseColors);

    const designTokens = colorGenerator.getDesignTokens();

    return {
      baseColors,
      description: themeInstance.description,
      designTokens,
      displayName: themeInstance.displayName,
      instance: themeInstance,
      name: themeName,
      typography: themeInstance.typography,
    };
  }

  static async generateThemes(): Promise<ThemeProps[]> {
    return Promise.all(themes.map(theme => Theme.generateTheme(theme)));
  }
}

export type { ThemeName, ThemeProps };

export { defaultThemeBaseColors, Theme, themes };

