import { converter, formatHex, parse } from 'culori';

import {
  compareShadeValues,
  extractShadeValue,
  lightnessAdjustments,
  type ShadeValue,
  standardShadeValues,
} from './shade';
import { defaultThemeBaseColors } from './theme';

// ----------------------------------------------------------------------------
// TYPES
// ----------------------------------------------------------------------------
type ColorCategory =
  | 'accent'
  | 'error'
  | 'info'
  | 'neutral'
  | 'primary'
  | 'secondary'
  | 'success'
  | 'warning';

const isShadeValue = (val: number): val is ShadeValue => {
  return (standardShadeValues as readonly number[]).includes(val);
};

interface ColorConfig {
  readonly classes: readonly string[];
  readonly colors: ColorToken;
  readonly css: string;
  readonly name: string;
}
type ColorPalette = Record<ColorCategory, string>;
type ColorProperties = Record<ShadeValue, string>;
type ColorScheme = 'dark' | 'light' | 'system';
type ColorSchemePalette = Record<
  FilteredColorScheme,
  Record<ShadeValue, string>
