const Input = forwardRef(
  <C extends ElementType = 'input'>(
    {
      as,
      children,
      className = '',
      variants = [] as StyleConfig<InputVariant>[],
      ...props
    }: Readonly<ComponentProps<C>>,
    forwardedRef: any
