      variants.length > 0
        ? variants.flatMap((v: Readonly<InputStyle>) => Object.keys(v.variants).filter((k): k is InputVariant => k in InputStyleClass.variants))
        : (['primary'] as InputVariant[]);

    const classes = [
      InputStyleClass.base,
      getStyleClasses(InputStyleClass, finalVariants),
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <Component className={classes} ref={forwardedRef} {...props}>
        {children}
      </Component>
    );
  }
);

Input.displayName = 'Input';

